    detailTab: oneOf(["materials", "market", "history"]),
    settingsTab: oneOf(["general", "virtual", "backup", "help"]),
    sort: oneOf(["saved", "name", "market", "profit", "wage", "margin", "own", "reference"]),
    direction: oneOf([1, -1]),
