const MOONCAKE_COMMUNITY_ENHANCING_SPEED_TYPE_HRID = '/community_buff_types/enhancing_speed';

const MOONCAKE_COMMUNITY_ENHANCING_SPEED_SOURCE_HRID = '/buff_uniques/enhancing_community_buff';

const MOONCAKE_ENHANCING_ACTION_TYPE_HRID = '/action_types/enhancing';

function mooncakeNormalizeVirtualEnhancingCommunityBuffLevel(value) {
        if (value === 'system' || value === 'follow-system' || value === 'follow_system' || value == null || value === '') {
            return 'system';
        }
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) return 'system';
        return Math.max(0, Math.min(20, Math.round(numeric)));
    }

function mooncakeIsEnhancingCommunityBuffEnabled() {
        return config.features?.enhancingCommunityBuff !== false;
    }

function mooncakeGetVirtualEnhancingCommunityBuffLevel() {
        return mooncakeNormalizeVirtualEnhancingCommunityBuffLevel(
            config.virtual?.community_enhancing_speed_level
        );
    }

function mooncakeGetCommunityEnhancingSpeedDefinition() {
        const initData = getInitClientData?.();
        const buff = initData?.communityBuffTypeDetailMap?.[MOONCAKE_COMMUNITY_ENHANCING_SPEED_TYPE_HRID]?.buff;
        const base = Number(buff?.flatBoost);
        const perLevel = Number(buff?.flatBoostLevelBonus);
        return {
            // The live init data currently defines level 1 as 20% and each
            // following level as +0.5%. Keep the data values authoritative.
            base: Number.isFinite(base) ? base : 0.20,
            perLevel: Number.isFinite(perLevel) ? perLevel : 0.005
        };
    }

function mooncakeGetCommunityEnhancingSpeedBonusForLevel(level) {
        const normalizedLevel = Math.max(0, Math.min(20, Math.round(Number(level) || 0)));
        if (!normalizedLevel) return 0;
        const definition = mooncakeGetCommunityEnhancingSpeedDefinition();
        // Keep the data-defined percentage stable (for example level 20 is
        // exactly 29.5%, not a binary floating-point tail in cache keys/UI).
        return Math.round((definition.base + definition.perLevel * (normalizedLevel - 1)) * 100000) / 1000;
    }

function mooncakeGetLiveEnhancingCommunityBuffLevel() {
        const buffs = mooncakeCollectionValues(
            mooncakeGetMapEntry(characterCommunityActionTypeBuffsMap, MOONCAKE_ENHANCING_ACTION_TYPE_HRID)
        );
        if (!buffs.length) return 0;
        const definition = mooncakeGetCommunityEnhancingSpeedDefinition();
        for (const buff of buffs) {
            const uniqueHrid = String(buff?.uniqueHrid || '');
            const typeHrid = String(buff?.typeHrid || '');
            if (uniqueHrid !== MOONCAKE_COMMUNITY_ENHANCING_SPEED_SOURCE_HRID && typeHrid !== '/buff_types/action_speed') continue;
            const directLevel = Number(buff?.communityBuffLevel ?? buff?.communityLevel ?? buff?.level);
            if (Number.isFinite(directLevel)) return Math.max(0, Math.min(20, Math.round(directLevel)));
            const flatBoost = Number(buff?.flatBoost);
            if (!Number.isFinite(flatBoost) || !(definition.perLevel > 0)) continue;
            const inferred = Math.round((flatBoost - definition.base) / definition.perLevel) + 1;
            const expectedFlatBoost = definition.base + definition.perLevel * (inferred - 1);
            if (inferred >= 1 && inferred <= 20 && Math.abs(flatBoost - expectedFlatBoost) < 1e-6) return inferred;
        }
        return 0;
    }

function mooncakeGetEffectiveEnhancingCommunityBuffLevel() {
        const virtualLevel = config.virtual?.enabled ? mooncakeGetVirtualEnhancingCommunityBuffLevel() : 'system';
        if (virtualLevel !== 'system') return virtualLevel;
        return mooncakeIsEnhancingCommunityBuffEnabled() ? mooncakeGetLiveEnhancingCommunityBuffLevel() : 0;
    }

