(function initReservePlan(root) {
  "use strict";
  const app = (root.MWILayuEnhancement = root.MWILayuEnhancement || {});
  const t = text => app.i18n ? app.i18n.t(text) : text;
  const storageKey = "mwi-layu:reserve-plan:v1";
  const key = item => `${item?.itemHrid}:${item?.enhancementLevel}`;
  const validCount = value => Number.isSafeInteger(value) && value >= 0;
  function validate(rows) {
    if (!Array.isArray(rows) || rows.length > 10000 || new Set(rows.map(key)).size !== rows.length || rows.some(row =>
      !row || Object.keys(row).some(field => !["itemHrid", "enhancementLevel", "name", "minimum"].includes(field)) ||
      !/^\/items\/[a-z0-9_]+$/.test(row.itemHrid) || !Number.isInteger(row.enhancementLevel) || row.enhancementLevel < 1 || row.enhancementLevel > 20 ||
      typeof row.name !== "string" || !row.name || row.name.length > 160 || !validCount(row.minimum) || row.minimum < 1 || row.minimum > 1000000)) {
      throw new Error(t("常备数量数据异常，原数据已保留"));
    }
    return rows;
  }
  function create(storage = root.localStorage) {
    const read = owner => owner ? validate(JSON.parse(storage.getItem(`${storageKey}:${owner}`) || "[]")) : [];
    return Object.freeze({read, set(owner, item, minimum) {
      if (!owner) throw new Error(t("角色尚未就绪"));
      if (!validCount(minimum) || minimum > 1000000) throw new Error(t("常备数量须为 0～1,000,000 的整数"));
      const rows = read(owner).filter(row => key(row) !== key(item));
      if (minimum) rows.push({itemHrid:item.itemHrid, enhancementLevel:item.enhancementLevel, name:item.name, minimum});
      storage.setItem(`${storageKey}:${owner}`, JSON.stringify(validate(rows)));
    }});
  }
  function recommendations(rules, {wages, own, summary, error = ""}) {
    const byItem = new Map();
    for (const project of summary?.projects || []) {
      const id = key(project.item);
      if (!byItem.has(id)) byItem.set(id, []);
      byItem.get(id).push(project);
    }
    return rules.map(item => {
      const owned = app.enhancementScheduleUI.ownedEquipment(item, wages, own);
      const matching = summary?.projects ? byItem.get(key(item)) || [] : null;
      let pending = matching ? 0 : null;
      for (const project of matching || []) {
        if (!validCount(project.item.quantity) || !validCount(project.completed) || project.completed > project.item.quantity) { pending = null; break; }
        pending += project.item.quantity - project.completed;
      }
      const known = !error && owned.total != null && validCount(pending);
      return {item, owned:owned.total, pending, gap:known ? Math.max(0, item.minimum - owned.total - pending) : null};
    });
  }
  // Preview target-count allocations in memory. Existing manual targets deduct
  // finished inventory, so adding N unfinished units can require a larger target.
  // Commit all selected additions in one validated storage write, never game actions.
  function add({owner, keys, rules, store, context}) {
    const selected = new Set(keys), before = store.read(owner);
    const storage = new Map([[`${app.enhancementSchedule.storageKey}:${owner}`, JSON.stringify(before)]]);
    const draft = app.enhancementSchedule.create({getItem:key => storage.get(key) ?? null, setItem:(key,value) => storage.set(key,value)});
    const additions = new Map();
    const current = () => recommendations(rules.read(owner), context(draft.read(owner)));
    const initial = current().filter(row => selected.has(key(row.item)));
    if (!initial.length || initial.some(row => row.gap == null)) throw new Error(t("库存、挂单或计划尚未就绪，暂不能加入补货计划"));
    for (let round = 0; round < 3; round++) {
      const missing = current().filter(row => selected.has(key(row.item)) && row.gap > 0);
      if (!missing.length) break;
      for (const row of missing) {
        const id = key(row.item), previous = additions.get(id);
        additions.set(id, {...row.item, quantity:(previous?.quantity || 0) + row.gap});
      }
      draft.addMany(owner, missing.map(row => ({...row.item,quantity:row.gap})));
    }
    if (current().some(row => selected.has(key(row.item)) && (row.gap == null || row.gap > 0))) throw new Error(t("补货计划核算未完成，请刷新后重试"));
    if (JSON.stringify(store.read(owner)) !== JSON.stringify(before)) throw new Error(t("计划已变化，请重新加入"));
    if (additions.size) store.addMany(owner, [...additions.values()]);
    return initial.reduce((sum,row) => sum + row.gap, 0);
  }
  app.reservePlan = Object.freeze({storageKey, key, validate, create, recommendations, add});
})(globalThis);


