        let stored;
        if (path.startsWith("material.")) stored = value.preferences.baseItemCostPricePolicy.material[Number(path.split(".")[1])] || "";
        else if (path.startsWith("threshold.")) stored = value.preferences.hourlyWageColorProfile.thresholdsM[Number(path.split(".")[1])];
        else if (path.startsWith("color.")) stored = value.preferences.hourlyWageColorProfile.colors[path.split(".")[1]];
        else stored = path.split(".").reduce((object, key) => object?.[key], value);
